<script setup lang="ts">import {onMounted,ref} from 'vue';import {harnessApi} from '../runtime-client/api';const rows=ref<any[]>([]);onMounted(async()=>rows.value=await harnessApi.capabilities());</script>
<template><main class="harness-admin"><h1>Capability Catalog</h1><article v-for="c in rows" :key="c.name+'@'+c.version" class="capability"><header><h2>{{c.name}} <small>@{{c.version}}</small></h2><span class="badge">{{c.riskLevel}}</span></header><p>{{c.description}}</p><p>Permission: <code>{{c.requiredPermission||'none'}}</code></p><details><summary>Input schema</summary><pre>{{JSON.stringify(c.inputSchema,null,2)}}</pre></details><details><summary>Output schema</summary><pre>{{JSON.stringify(c.outputSchema,null,2)}}</pre></details></article></main></template>
